    assert.equal(reloaded.get('#task-filter').value, 'All');
    assert.equal(reloaded.get('#priority-filter').value, 'All');
    assert.deepEqual(reloaded.get('#tasks').children.map((row) => row.children[3].children[1].value),
      ['Low', 'Normal', 'High']);
